world_checks.check_baseline_pages_and_databases:
def check(world):
    state = world.state()
    pages = state.get("pages", [])
    databases = state.get("databases", [])
    if len(pages) < 8:
        return f"expected at least 8 meeting pages, got {len(pages)}"
    if len(databases) < 2:
        return f"expected at least 2 databases, got {len(databases)}"
    return None

world_checks.check_clock_and_async_tasks:
def check(world):
    state = world.state()
    clock = state.get("clock", [])
    tasks = state.get("async_tasks", [])
    if not clock or not clock[0].get("now"):
        return "clock table missing current time entry"
    if len(tasks) < 2:
        return f"expected at least 2 async task fixtures, got {len(tasks)}"
    return None

world_checks.check_users_and_actions_present:
def check(world):
    state = world.state()
    users = state.get("workspace_users", [])
    if len(users) < 6:
        return f"expected at least 6 workspace users, got {len(users)}"
    return None
